@@ -0,0 +1,10 @@
+import type { Order } from "./orders";
+
+const HEADER = ["订单号", "下单时间", "金额", "状态"];
+const cell = (value: string) => (/[",\n]/.test(value) ? `"${value.replaceAll('"', '""')}"` : value);
+
+export function ordersCsv(orders: Order[]): string {
+  const rows = orders.map((o) => [o.id, o.createdAt.toISOString(), o.amount.toFixed(2), o.status].map(cell).join(","));
+  return `${[HEADER.join(","), ...rows].join("\r\n")}\r\n`;
+}
